<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRoute} from 'vue-router';import {api,session,money,date,statuses,notify,type Row} from '../api';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import Modal from '../components/Modal.vue'
const id=useRoute().params.id;const order=ref<Row|null>(null),error=ref(''),formError=ref(''),mode=ref(''),busy=ref(false),form=ref<Row>({}),parts=ref<Row[]>([]),employees=ref<Row[]>([]);const admin=computed(()=>session.user?.role==='ADMIN'),staff=computed(()=>session.user?.role!=='CLIENT'),closed=computed(()=>['DELIVERED','CANCELLED'].includes(order.value?.status));const transitions:Record<string,string[]>={RECEIVED:['DIAGNOSIS','CANCELLED'],DIAGNOSIS:['AWAITING_APPROVAL','CANCELLED'],AWAITING_APPROVAL:['IN_PROGRESS','DIAGNOSIS','CANCELLED'],IN_PROGRESS:['READY','AWAITING_APPROVAL','CANCELLED'],READY:['DELIVERED','IN_PROGRESS','CANCELLED'],DELIVERED:['IN_PROGRESS'],CANCELLED:[]};const next=computed(()=>(transitions[order.value?.status]||[]).filter(s=>admin.value||order.value?.status==='IN_PROGRESS'&&s==='READY'||order.value?.status==='RECEIVED'&&s==='DIAGNOSIS'))
async function load(){try{order.value=await api('/orders/'+id)}catch(e:any){error.value=e.message}}
async function open(m:string){formError.value='';mode.value=m;const o=order.value!;form.value=m==='quote'?{diagnosis:o.diagnosis||'',estimate:o.estimated_amount||0,version:o.version}:m==='status'?{status:next.value[0],reason:'',version:o.version}:m==='work'?{employeeId:o.assignments[0]?.employee_id||'',description:'',cost:0,price:0}:m==='payment'?{kind:'PAYMENT',amount:Math.max(0,o.totals.total-o.totals.paid),method:'CASH',reason:'Pago de servicio',reference:'',requestKey:crypto.randomUUID()}:m==='part'?{partId:'',orderId:Number(id),kind:'CONSUMPTION',quantity:1,reason:'Pieza utilizada en servicio',requestKey:crypto.randomUUID()}:{employeeId:''};if(m==='part')parts.value=await api('/parts');if(m==='assignment')employees.value=await api('/employees')}
async function save(){busy.value=true;formError.value='';try{const routes:Record<string,string>={quote:'quote',status:'status',work:'works',payment:'payments',assignment:'assignments'};await api(mode.value==='part'?'/inventory/movements':'/orders/'+id+'/'+routes[mode.value],mode.value==='quote'?'PUT':'POST',form.value);mode.value='';await load();notify('Orden actualizada')}catch(e:any){formError.value=e.message}finally{busy.value=false}}
async function finish(w:Row){try{await api('/orders/'+id+'/works/'+w.id+'/status','PUT',{status:'DONE'});await load();notify('Trabajo terminado')}catch(e:any){notify(e.message,'error')}}
onMounted(load)
</script>
<template><RouterLink to="/orders" class="back-link"><Icon name="back" :size="16"/>Todas las órdenes</RouterLink><p v-if="error" class="error">{{error}}</p><template v-if="order"><div class="page-heading"><div><p class="eyebrow">ORDEN #{{order.id}}</p><h1>{{order.vehicle.make}} {{order.vehicle.model}} <span class="model-year">{{order.vehicle.model_year}}</span></h1><p class="muted">{{order.vehicle.license_plate||'Sin matrícula'}} <span class="separator">·</span> {{order.customer.full_name}} <span class="separator">·</span> Ingreso {{date(order.received_at)}}</p></div><div class="button-row"><Badge :status="order.status"/><button v-if="staff&&next.length" class="btn primary" @click="open('status')">Actualizar estado<Icon name="arrow"/></button></div></div><div class="detail-grid"><div class="detail-main"><section class="panel detail-panel"><div class="panel-heading"><h2>Diagnóstico y presupuesto</h2><button v-if="admin&&!closed" class="text-link" @click="open('quote')">Editar</button></div><div class="detail-content"><p class="eyebrow">MOTIVO DE LA VISITA</p><p>{{order.complaint}}</p><p class="eyebrow spaced">DIAGNÓSTICO</p><p>{{order.diagnosis||'Aún no se ha registrado un diagnóstico.'}}</p><div class="quote-total"><span>Presupuesto propuesto</span><strong>{{money(order.estimated_amount)}}</strong></div></div></section><section class="panel detail-panel"><div class="panel-heading"><h2>Trabajos realizados <span class="count-pill">{{order.works.length}}</span></h2><button v-if="staff&&!closed" class="text-link" @click="open('work')"><Icon name="plus" :size="16"/>Agregar trabajo</button></div><div v-for="w in order.works" :key="w.id" class="work-row"><span class="stat-icon mint"><Icon name="wrench"/></span><div class="grow"><strong>{{w.description}}</strong><small>{{w.mechanic}}</small><Badge :status="w.status"/></div><div class="work-price"><strong>{{money(w.sale_price)}}</strong><button v-if="staff&&w.status==='IN_PROGRESS'&&!closed" class="text-link" @click="finish(w)">Marcar terminado</button></div></div><div v-if="!order.works.length" class="empty compact"><Icon name="wrench" :size="30"/><p>Los trabajos aparecerán aquí.</p></div></section><section class="panel detail-panel"><div class="panel-heading"><h2>Piezas utilizadas</h2><button v-if="staff&&!closed" class="text-link" @click="open('part')"><Icon name="plus" :size="16"/>Registrar pieza</button></div><div class="table-wrap"><table><thead><tr><th>Pieza</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th></tr></thead><tbody><tr v-for="p in order.parts"><td>{{p.name}}<small>{{p.kind==='RETURN'?'Devolución':'Consumo'}}</small></td><td>{{-Number(p.quantity)}}</td><td>{{money(p.unit_price)}}</td><td>{{money(-p.quantity*p.unit_price)}}</td></tr></tbody></table><div v-if="!order.parts.length" class="empty compact"><p>Sin piezas registradas.</p></div></div></section><section class="panel detail-panel"><div class="panel-heading"><h2>Cobros y anticipos</h2><button v-if="admin&&!closed" class="text-link" @click="open('payment')"><Icon name="plus" :size="16"/>Registrar cobro</button></div><div v-for="p in order.payments" class="payment-row"><span class="stat-icon mint"><Icon name="wallet"/></span><div class="grow"><strong>{{p.reason}}</strong><small>{{date(p.created_at)}} · {{({CASH:'Efectivo',CARD:'Tarjeta',TRANSFER:'Transferencia'} as Record<string,string>)[p.method]}}</small></div><strong>{{p.kind==='REFUND'?'-':''}}{{money(p.amount)}}</strong></div><div v-if="!order.payments.length" class="empty compact"><p>No hay pagos registrados.</p></div></section></div><aside><section class="panel summary-card"><p class="eyebrow">RESUMEN DEL SERVICIO</p><div class="summary-line"><span>Trabajos y piezas</span><strong>{{money(order.totals.total)}}</strong></div><div class="summary-line"><span>Pagado</span><strong>{{money(order.totals.paid)}}</strong></div><div class="balance"><span>Saldo pendiente</span><strong>{{money(order.totals.total-order.totals.paid)}}</strong></div><template v-if="admin"><div class="summary-line"><span>Costo directo</span><strong>{{money(order.totals.direct_cost)}}</strong></div><div class="summary-line"><span>Margen bruto</span><strong>{{money(order.totals.total-order.totals.direct_cost)}}</strong></div><small class="muted">Los costos internos solo los ve administración.</small></template></section><section class="panel detail-panel"><div class="panel-heading"><h2>Equipo asignado</h2><button v-if="admin&&!closed" class="text-link" aria-label="Asignar mecánico" @click="open('assignment')"><Icon name="plus" :size="18"/></button></div><div v-for="a in order.assignments" class="assigned-person"><span class="avatar pale">{{a.full_name.slice(0,2).toUpperCase()}}</span><strong>{{a.full_name}}</strong></div><p v-if="!order.assignments.length" class="empty compact">Aún sin asignar</p></section><section class="panel detail-panel"><div class="panel-heading"><h2>Historial de la orden</h2></div><div class="timeline"><div v-for="h in [...order.history].reverse()" class="timeline-item"><i></i><strong>{{statuses[h.new_status]}}</strong><p>{{h.reason}}</p><small>{{date(h.created_at)}}</small></div></div></section></aside></div><Modal v-if="mode" :title="({quote:'Diagnóstico y presupuesto',status:'Actualizar estado',work:'Agregar trabajo',part:'Registrar pieza',payment:'Registrar cobro',assignment:'Asignar mecánico'} as Record<string,string>)[mode]" :busy="busy" :error="formError" @close="mode=''" @submit="save"><template v-if="mode==='quote'"><label>Diagnóstico<textarea v-model="form.diagnosis" required></textarea></label><label>Presupuesto (MXN)<input v-model.number="form.estimate" type="number" min="0" step="0.01" required></label></template><template v-if="mode==='status'"><label>Nuevo estado<select v-model="form.status"><option v-for="s in next" :value="s">{{statuses[s]}}</option></select></label><label>Motivo / medio de autorización<input v-model="form.reason" required maxlength="80" placeholder="Ej. Autorizado por teléfono por el cliente"></label></template><template v-if="mode==='work'"><label>Mecánico<select v-model="form.employeeId" required><option disabled value="">Selecciona al responsable</option><option v-for="a in order.assignments" :value="a.employee_id">{{a.full_name}}</option></select></label><label>Trabajo<textarea v-model="form.description" required></textarea></label><template v-if="admin"><label>Costo directo<input v-model.number="form.cost" type="number" min="0" step="0.01" required></label><label>Precio al cliente<input v-model.number="form.price" type="number" min="0" step="0.01" required></label></template></template><template v-if="mode==='part'"><label>Pieza<select v-model="form.partId" required><option disabled value="">Selecciona una pieza</option><option v-for="p in parts" :value="p.id">{{p.name}} · {{Number(p.stock)}} disponibles</option></select></label><label>Operación<select v-model="form.kind"><option value="CONSUMPTION">Consumo</option><option value="RETURN">Devolución</option></select></label><label v-if="form.kind==='RETURN'">Consumo original<select v-model="form.reversalOf" required><option v-for="p in order.parts.filter((p:Row)=>p.kind==='CONSUMPTION'&&Number(p.part_id)===Number(form.partId))" :value="p.id">{{p.name}} · {{-p.quantity}} unidades</option></select></label><label>Cantidad<input v-model.number="form.quantity" type="number" min="0.001" step="0.001" required></label><label>Motivo<input v-model="form.reason" required></label></template><template v-if="mode==='payment'"><label>Operación<select v-model="form.kind"><option value="PAYMENT">Cobro / anticipo</option><option value="REFUND">Reembolso</option></select></label><label>Monto<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required></label><label>Método<select v-model="form.method"><option value="CASH">Efectivo</option><option value="CARD">Tarjeta</option><option value="TRANSFER">Transferencia</option></select></label><label>Motivo<input v-model="form.reason" required></label></template><label v-if="mode==='assignment'">Mecánico<select v-model="form.employeeId" required><option disabled value="">Selecciona un mecánico</option><option v-for="e in employees.filter(e=>e.role_code==='MECHANIC'&&e.enabled)" :value="e.id">{{e.full_name}}</option></select></label></Modal></template></template>
